<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfileGenderVO;

trait UserProfileGenderAccessor
{
    private ?UserProfileGenderVO $_gender = null;
    public function getGender(): ?string
    {
        return $this->_gender?->value();
    }
    public function gender(): ?UserProfileGenderVO
    {
        return $this->_gender;
    }
    public function isGenderChanged(?self $original = null): bool
    {
        return null !== $this->_gender && !$this->_gender->equals($original?->_gender);
    }
    public function withGender(UserProfileGenderVO|string|null $gender): self
    {
        $copy = clone $this;
        $copy->_gender = UserProfileGenderVO::from($gender);
        return $copy;
    }
}
